import {Study,STEP} from './simulation.js';
const canvas=document.querySelector('#scene'),ctx=canvas.getContext('2d'),sim=new Study(),remaining=document.querySelector('#remaining'),status=document.querySelector('#status'),hint=document.querySelector('#hint'),motion=document.querySelector('#reduced');
const sprites=await Promise.all([1,4,7,11,18].map(i=>new Promise(resolve=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>resolve(null);im.src=`assets/leaf-${String(i).padStart(2,'0')}.png`})));
let scale=1,ox=0,oy=0,width=0,height=0,raf=0,last=null,acc=0,pointer=null,pending=[],previous=null,velocity={x:0,y:0},pulse=0,trail=[],lastCount=54,userMotion=false;
const media=matchMedia('(prefers-reduced-motion: reduce)');motion.checked=media.matches;sim.setReduced(media.matches);
function resize(){const r=canvas.getBoundingClientRect();width=r.width;height=r.height;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);scale=Math.min(width/900,height/800);ox=(width-900*scale)/2;oy=(height-800*scale)/2;previous=null;pending=[];wake()}
function world(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left-ox)/scale,y:(e.clientY-r.top-oy)/scale,t:e.timeStamp}}
function wake(){if(!raf&&!document.hidden)raf=requestAnimationFrame(frame)}
function finish(){if(pointer!==null&&canvas.hasPointerCapture(pointer))canvas.releasePointerCapture(pointer);pointer=null;previous=null;pending=[];velocity={x:0,y:0};hint.textContent='按住并划动 · 风只经过你触碰的地方';wake()}
canvas.addEventListener('pointerdown',e=>{if(pointer!==null||(e.pointerType==='mouse'&&e.button!==0))return;pointer=e.pointerId;canvas.setPointerCapture(pointer);previous=world(e);pending=[];velocity={x:0,y:0};sim.beginGesture();hint.textContent='风正在经过';wake()});
canvas.addEventListener('pointermove',e=>{if(e.pointerId!==pointer)return;pending.push(world(e));if(pending.length>64)pending.shift();wake()});
for(const type of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(type,e=>{if(e.pointerId===pointer)finish()});window.addEventListener('blur',finish);
function input(){if(!pending.length)return;const batch=pending.splice(0),a=previous;for(const p of batch){if(previous){const dt=(p.t-previous.t)/1000;if(dt>0&&dt<.1){let vx=(p.x-previous.x)/dt,vy=(p.y-previous.y)/dt,s=Math.min(1,1800/(Math.hypot(vx,vy)||1)),k=1-Math.exp(-dt/.045);velocity.x+=(vx*s-velocity.x)*k;velocity.y+=(vy*s-velocity.y)*k}else velocity={x:0,y:0}}previous=p}if(a&&previous){const distance=Math.hypot(previous.x-a.x,previous.y-a.y),count=Math.max(1,Math.min(12,Math.ceil(distance/20)));for(let i=0;i<count;i++){const from={x:a.x+(previous.x-a.x)*i/count,y:a.y+(previous.y-a.y)*i/count},to={x:a.x+(previous.x-a.x)*(i+1)/count,y:a.y+(previous.y-a.y)*(i+1)/count};sim.emit(from,to,{x:velocity.x*2.2*Math.min(.05,(previous.t-a.t)/1000)/STEP/count,y:velocity.y*2.2*Math.min(.05,(previous.t-a.t)/1000)/STEP/count})}if(!sim.reduced){trail.push({x:previous.x,y:previous.y,age:0});if(trail.length>12)trail.shift()}}}
function frame(t){raf=0;const dt=last===null?0:Math.min(.05,(t-last)/1000);last=t;acc+=dt;input();let n=0;while(acc>=STEP&&n++<6){if(pulse>0){pulse-=STEP;const p=sim.point(sim.branches[3],.6);sim.emit({x:p.x-45,y:p.y+50},{x:p.x+25,y:p.y-40},{x:1150,y:-650})}sim.step();for(const p of trail)p.age+=STEP;trail=trail.filter(p=>p.age<.45);acc-=STEP}render();remaining.textContent=sim.remaining;if(sim.remaining!==lastCount){lastCount=sim.remaining}if(pointer!==null||pulse>0||sim.active||trail.length)wake();else{last=null;acc=0;for(const b of sim.branches){b.theta=b.omega=0}sim.transform();for(const l of sim.leaves)if(l.state==='attached')Object.assign(l,sim.anchor(l));render();const fallen=54-sim.remaining;status.textContent=fallen?`风带走了 ${fallen} 片叶子，枝头还留着 ${sim.remaining} 片。`:'每一片离开的叶子，都会留下自己的位置。'}}
function render(){ctx.clearRect(0,0,width,height);ctx.save();ctx.translate(ox,oy);ctx.scale(scale,scale);
 const glow=ctx.createRadialGradient(500,420,40,500,420,380);glow.addColorStop(0,'rgba(225,228,203,.20)');glow.addColorStop(1,'rgba(225,228,203,0)');ctx.fillStyle=glow;ctx.fillRect(0,0,900,800);
 ctx.strokeStyle='rgba(169,174,146,.20)';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(108,730);ctx.bezierCurveTo(320,737,690,732,800,729);ctx.stroke();
 for(const b of sim.branches){ctx.save();ctx.translate(b.origin.x,b.origin.y);ctx.rotate(b.angle);for(let i=0;i<28;i++){const t=i/28,p0=point(b.c,t),p1=point(b.c,(i+1)/28);ctx.strokeStyle=i%3?'#8a8067':'#958b72';ctx.lineWidth=Math.max(.6,b.width*(1-t*.92));ctx.lineCap='round';ctx.beginPath();ctx.moveTo(p0.x,p0.y);ctx.lineTo(p1.x,p1.y);ctx.stroke()}ctx.restore()}
 for(const l of sim.leaves){if(l.state!=='attached')continue;const b=sim.branches[l.branch],p=sim.point(b,l.t);ctx.strokeStyle='#929270';ctx.lineWidth=.75;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.quadraticCurveTo((p.x+l.x)/2+3,(p.y+l.y)/2,l.x,l.y);ctx.stroke();leaf(l)}
 for(const l of sim.leaves)if(!['attached','gone'].includes(l.state))leaf(l);
 if(trail.length>1){ctx.beginPath();ctx.moveTo(trail[0].x,trail[0].y);for(const p of trail)ctx.lineTo(p.x,p.y);ctx.strokeStyle=`rgba(135,151,113,${Math.max(0,.18*(1-trail[0].age/.45))})`;ctx.lineWidth=1.5;ctx.stroke()}ctx.restore()}
function point(c,t){const u=1-t;return{x:u*u*u*c[0][0]+3*u*u*t*c[1][0]+3*u*t*t*c[2][0]+t*t*t*c[3][0],y:u*u*u*c[0][1]+3*u*u*t*c[1][1]+3*u*t*t*c[2][1]+t*t*t*c[3][1]}}
function leaf(l){ctx.save();ctx.globalAlpha=l.alpha;ctx.translate(l.x,l.y);ctx.rotate(l.angle);if(l.state==='falling'&&!sim.reduced)ctx.scale(.6+.4*Math.abs(Math.cos(l.age*3)),1);const im=sprites[l.sprite];if(im){const w=l.size,h=l.size*im.height/im.width;ctx.drawImage(im,-w*.5,-h*.85,w,h)}else{ctx.fillStyle=l.id%3?'#a5ad73':'#cfba72';ctx.beginPath();ctx.moveTo(0,0);ctx.bezierCurveTo(-25,-15,-15,-30,0,-38);ctx.bezierCurveTo(20,-20,20,-10,0,0);ctx.fill()}ctx.restore()}
document.querySelector('#breeze').addEventListener('click',()=>{sim.beginGesture();pulse=.55;status.textContent='一阵轻风，拂过枝头。';wake()});document.querySelector('#reset').addEventListener('click',()=>{finish();sim.reset();sim.setReduced(motion.checked);pulse=0;trail=[];last=null;acc=0;status.textContent='枝叶已重新长满。';wake()});motion.addEventListener('change',()=>{userMotion=true;sim.setReduced(motion.checked);trail=[];status.textContent=motion.checked?'已减少动态：叶片在原位淡出。':'已恢复枝叶摇摆与飘落。';wake()});media.addEventListener('change',e=>{if(!userMotion){motion.checked=e.matches;sim.setReduced(e.matches);wake()}});document.addEventListener('visibilitychange',()=>{if(document.hidden){finish();cancelAnimationFrame(raf);raf=0;last=null;acc=0;sim.wind=[];pulse=0;trail=[]}else wake()});new ResizeObserver(resize).observe(canvas);resize();
